// Standalone multicolor bitmap part. SYS entry is generated by KickAssembler.
.var picture = LoadBinary("assets/giana5.koa")
.var lighting = LoadBinary("assets/lighting.bin")
.import source "assets/scene.asm"
.assert "Source is a standard Koala bitmap", picture.getSize(), 10003

.const SCREEN = $0400
.const BITMAP = $2000
.const SCREEN_DATA = $c000
.const COLOR_DATA = SCREEN_DATA + 1000
.const BACKGROUND = picture.get(10002) & $0f
.const TV_PIXELS = TV_WIDTH * 4
.const TV_UPDATE_RASTER = 144
.const MUSIC_UPDATE_RASTER = 64
.const CORNER_SPLIT_RASTER = 115
.const SCROLL_FRAME_INTERVAL = 4
.const LIGHT_UPDATE_RASTER = 250
.const LIGHT_FRAME_INTERVAL = 16
.const TILE_POINTER = $fb
.const COLOR_BITS = $fd
.const ACTOR_X_BASE = TV_COLUMN * 8 + 24
.const ACTOR_Y_BASE = TV_ROW * 8 + 50
.const CORNER_SPRITES = $0200

* = $a000 "Terrain tiles and map"
    .import source "terrain.asm"
    .import source "terrain-level2.asm"
.assert "Both stages share the map width", TERRAIN2_MAP_WIDTH, TERRAIN_MAP_WIDTH
.assert "Both stages share the TV height", TERRAIN2_MAP_HEIGHT, TERRAIN_MAP_HEIGHT
.assert "Both stages share the picture background", TERRAIN2_BACKGROUND, TERRAIN_BACKGROUND
.assert "Level 2 tile IDs fit in one byte", TERRAIN2_TILE_COUNT <= 256, true
.assert "Level 2 tile addresses start on a page boundary", <terrain2Tiles, 0

* = $1a00 "Level 2 original Giana poses"
tinySpriteFrames2:
    .import binary "assets/level2-sprites.bin"
.assert "Level 2 has eight Giana sprite planes", * - tinySpriteFrames2, 512
.assert "Level 2 map avoids its actor atlas", terrain2MapEnd <= tinySpriteFrames2, true
.assert "Level 2 actor sources stay below the bitmap", * <= $2000, true

* = $1c00 "Original crab, spring and bee frames"
    .import source "assets/enemies.asm"
.assert "Extra enemy art stays below the bitmap", * <= $2000, true

* = $41c0 "Original Giana in-game music"
    .import source "assets/music.asm"
.assert "Music fits below the renderer", musicOriginalEnd <= $6000, true

* = $0c00 "Tiny original sprites"
    .import source "assets/sprites.asm"
spriteWork0: .fill 64, 0
spriteWork1: .fill 64, 0
spriteWork2: .fill 64, 0
tvHighlightSprite:
    .import binary "assets/tv-highlight.bin"
.assert "TV highlight is one hires sprite", * - tvHighlightSprite, 64
.assert "TV highlight is 64-byte aligned", tvHighlightSprite & $3f, 0
spriteWork3: .fill 64, 0
.assert "Sprite atlas and working frames avoid character ROM", * <= $1000, true

BasicUpstart2(start)

start:
    sei
    cld

    // Read the terrain RAM beneath BASIC while keeping KERNAL and I/O mapped.
    lda $00
    ora #7
    sta $00
    lda $01
    and #$f8
    ora #6
    sta $01

    // Keep the display blank while copying the two color maps.
    lda #$0b
    sta $d011
    lda #0
    sta $d015
    sta $d01a
    sta $d020
    lda #$7f
    sta $dc0d
    sta $dd0d
    lda $dc0d
    lda $dd0d
    lda #$0f
    sta $d019

    // Select VIC bank 0 without changing the other CIA2 port bits.
    lda $dd02
    ora #3
    sta $dd02
    lda $dd00
    ora #3
    sta $dd00

    ldx #0
copyPages:
    .for (var page = 0; page < 3; page++) {
        lda SCREEN_DATA + page * $100,x
        sta SCREEN + page * $100,x
        lda COLOR_DATA + page * $100,x
        sta $d800 + page * $100,x
    }
    inx
    bne copyPages

    ldx #0
copyTail:
    lda SCREEN_DATA + $300,x
    sta SCREEN + $300,x
    lda COLOR_DATA + $300,x
    sta $db00,x
    inx
    cpx #232
    bne copyTail

    lda #$18
    sta $d018
    sta $d016
    lda #BACKGROUND
    sta $d021

    jsr initTerrain
    jsr applyLight
    jsr initSprites

    // The native cue selector resets the driver itself. Cue 1 is SID subtune 3.
    lda #MUSIC_LEVEL1_CUE
    clc
    jsr MUSIC_SELECT

    // Reveal the complete picture during the lower border.
waitBorder:
    lda $d011
    bpl waitBorder
    lda #$3b
    sta $d011
display:
    lda $d012
    cmp #MUSIC_UPDATE_RASTER
    bne display
musicFrameStart:
    jsr MUSIC_PLAY
musicFrameDone:
waitCornerSplit:
    lda $d012
    cmp #CORNER_SPLIT_RASTER
    bne waitCornerSplit
cornerSplitStart:
    // The top-left DMA has finished; reuse its slot for the bottom-left mask.
    lda #(CORNER_SPRITES / 64) + 2
    sta SCREEN + $3f8
    lda #ACTOR_Y_BASE + TV_HEIGHT * 8 - 21
    sta $d001
cornerSplitDone:
waitTVUpdate:
    lda $d012
    cmp #TV_UPDATE_RASTER
    bne waitTVUpdate
frameStart:
    jsr restoreLeftTopCorner
cornerTopRestored:
    lda levelTransition
    beq !normalFrame+
    jsr advanceLevelTransition
    jmp checkLight
!normalFrame:
    // Sprite copies use a separate frame from terrain and room lighting.
    lda frameCounter
    and #3
    bne !noSprites+
    jsr updateSprites
!noSprites:
    dec scrollCountdown
    bne checkLight
    jsr scrollTerrain
    jsr updateColors
    lda #SCROLL_FRAME_INTERVAL
    sta scrollCountdown
    inc levelCameraStep
    bne !checkLevelEnd+
    inc levelCameraStep + 1
!checkLevelEnd:
    ldx activeLevel
    lda levelCameraStep
    cmp levelEndStepLow,x
    bne checkLight
    lda levelCameraStep + 1
    cmp levelEndStepHigh,x
    bne checkLight
    lda #$ff
    sta levelTransition
checkLight:
    dec lightCountdown
    bne countFrame
    inc lightPhase
    lda lightPhase
    and #3
    sta lightPhase
    tax
    lda lightSequence,x
    sta lightLevel
    // The marked room reaches the bottom of the picture. Change all colors
    // after its last scanline so one displayed frame always has one light level.
!waitLightBorder:
    lda $d012
    cmp #LIGHT_UPDATE_RASTER
    bne !waitLightBorder-
    jsr applyLight
    lda #LIGHT_FRAME_INTERVAL
    sta lightCountdown
countFrame:
    inc frameCounter
    bne frameDone
    inc frameCounter+1
frameDone:
    // Short hold frames must leave raster 144 before polling for the next one.
!leaveRaster:
    lda $d012
    cmp #TV_UPDATE_RASTER
    beq !leaveRaster-
    jmp display

.var terrainMapReadOperands = List()
.var terrainTileHighOperands = List()
prepareColumn:
    // Map rows contain tile IDs; each ID selects eight packed bitmap bytes.
    ldx incomingTile
    .for (var row = 0; row < TV_HEIGHT; row++) {
        .eval terrainMapReadOperands.add(* + 1)
        lda terrainMapStart + row * TERRAIN_MAP_WIDTH,x
        tay
        asl
        asl
        asl
        sta TILE_POINTER
        tya
        lsr
        lsr
        lsr
        lsr
        lsr
        clc
        .eval terrainTileHighOperands.add(* + 1)
        adc #>terrainTiles
        sta TILE_POINTER+1
        ldy #0
        .for (var line = 0; line < 8; line++) {
            lda (TILE_POINTER),y
            sta incomingColumn + row * 8 + line
            .if (line < 7) {
                iny
            }
        }
    }
    rts

.assert "Setup fits below the sprite atlas", * <= $0c00, true

* = BITMAP "Koala bitmap"
    .fill 8000, picture.get(i + 2)
.assert "Bitmap fits below original music", * <= MUSIC_LOAD, true

* = SCREEN_DATA "Koala screen and color sources"
    .fill 2000, picture.get(i + 8002)
.assert "PRG data avoids the I/O window", * <= $d000, true

.assert "Terrain fits below the color sources", terrainDataEnd <= SCREEN_DATA, true
* = $6000 "TV scroll renderer"

scrollTerrain:
    // Feed regions left to right while each neighbor still contains old data.
    // Only crossing a fixed seam changes the row of the pixel stream.
    .for (var region = 0; region < TERRAIN_PERSPECTIVE_REGIONS - 1; region++) {
        .var rows = TERRAIN_PERSPECTIVE_TRANSFER_ROWS.get(region)
        .var firstColumn = TERRAIN_PERSPECTIVE_COLUMNS.get(region)
        .var nextColumn = TERRAIN_PERSPECTIVE_COLUMNS.get(region + 1)
        .for (var line = 0; line < TV_HEIGHT * 8; line++) {
            .var sourceLine = rows.get(line)
            .if (sourceLine >= 0) {
                .var address = BITMAP + ((TV_ROW + floor(line / 8)) * 40 + TV_COLUMN) * 8 + (line & 7)
                .var source = BITMAP + ((TV_ROW + floor(sourceLine / 8)) * 40 + TV_COLUMN + nextColumn) * 8 + (sourceLine & 7)
                lda source
                asl
                .for (var column = nextColumn - 1; column >= firstColumn; column--) {
                    rol address + column * 8
                }
                asl
                .for (var column = nextColumn - 1; column >= firstColumn; column--) {
                    rol address + column * 8
                }
            }
        }
    }

    // Shift right-to-left twice. A retains the two incoming pixel bits while
    // carry propagates through the unwarped final region's bitmap bytes.
    .for (var line = 0; line < TV_HEIGHT * 8; line++) {
        .var address = BITMAP + ((TV_ROW + floor(line / 8)) * 40 + TV_COLUMN) * 8 + (line & 7)
        lda incomingColumn + line
        asl
        .for (var column = TV_WIDTH - 1; column >= TERRAIN_PERSPECTIVE_COLUMNS.get(TERRAIN_PERSPECTIVE_REGIONS - 1); column--) {
            rol address + column * 8
        }
        asl
        .for (var column = TV_WIDTH - 1; column >= TERRAIN_PERSPECTIVE_COLUMNS.get(TERRAIN_PERSPECTIVE_REGIONS - 1); column--) {
            rol address + column * 8
        }
        // Keep the remaining source pixels ready for the next PAL frame.
        asl incomingColumn + line
        asl incomingColumn + line

    }

    inc tilePixelX
    lda tilePixelX
    cmp #4
    bne !done+
    lda #0
    sta tilePixelX
    inc incomingTile
    lda incomingTile
    and #TERRAIN_MAP_WIDTH - 1
    sta incomingTile
    jsr prepareColumn
!done:
    rts

updateColors:
    // Reuse the finished tile fetch's pointer for the current color phase.
    ldy tilePixelX
    lda perspectiveAccentPhaseLow,y
    sta TILE_POINTER
    lda perspectiveAccentPhaseHigh,y
    sta TILE_POINTER+1
    lda incomingTile
    sec
    sbc #TV_WIDTH
    and #TERRAIN_MAP_WIDTH - 1
    tay

    // Each region selects its own projected green/yellow column flags.
    .for (var region = 0; region < TERRAIN_PERSPECTIVE_REGIONS; region++) {
        .for (var column = TERRAIN_PERSPECTIVE_COLUMNS.get(region); column < TERRAIN_PERSPECTIVE_COLUMNS.get(region + 1); column++) {
            .if (region > 0 && column == TERRAIN_PERSPECTIVE_COLUMNS.get(region)) {
                ldx tilePixelX
                lda perspectiveAccentPhaseLow + region * 4,x
                sta TILE_POINTER
                lda perspectiveAccentPhaseHigh + region * 4,x
                sta TILE_POINTER+1
            }
            lda (TILE_POINTER),y
            sta COLOR_BITS
            .for (var row = 0; row < TV_HEIGHT; row++) {
                lsr COLOR_BITS
                .if ((TERRAIN_PERSPECTIVE_BLACK_ROWS.get(region) & (1 << row)) != 0) {
                    lda #0
                } else {
                    lda #5
                    bcc !green+
                    lda #7
!green:
                }
                sta $d800 + (TV_ROW + row) * 40 + TV_COLUMN + column
            }
            .if (column < TV_WIDTH - 1) {
                iny
                tya
                and #TERRAIN_MAP_WIDTH - 1
                tay
            }
        }
    }
    rts

applyLight:
    // Every level comes from the original Koala colors, never from the previous
    // light level. Black, brown, red, dark gray and dark blue slots stay fixed
    // in all three tables.
    ldx lightLevel
    .for (var index = 0; index < LIGHT_TILE_COUNT; index++) {
        .var cell = LIGHT_CELLS.get(index)
        lda lightScreenColors + index * 3,x
        sta SCREEN + cell
        lda lightColorRam + index * 3,x
        sta $d800 + cell
    }
    rts

lightScreenColors:
    .fill LIGHT_TILE_COUNT * 3, lighting.get(i)
lightColorRam:
    .fill LIGHT_TILE_COUNT * 3, lighting.get(LIGHT_TILE_COUNT * 3 + i)
lightSequence:
    .byte 0, 1, 2, 1
lightPhase: .byte 0
lightLevel: .byte 0
// Terrain changes every fourth frame. Offset lighting by two frames so the
// terrain renderer and the full room palette never share an update frame.
lightCountdown: .byte LIGHT_FRAME_INTERVAL - 2

perspectiveAccentPhaseLow:
    .for (var region = 0; region < TERRAIN_PERSPECTIVE_REGIONS; region++) {
        .for (var phase = 0; phase < 4; phase++) {
            .byte <(TERRAIN_PERSPECTIVE_ACCENT_MAPS.get(region) + phase * 128)
        }
    }
perspectiveAccentPhaseHigh:
    .for (var region = 0; region < TERRAIN_PERSPECTIVE_REGIONS; region++) {
        .for (var phase = 0; phase < 4; phase++) {
            .byte >(TERRAIN_PERSPECTIVE_ACCENT_MAPS.get(region) + phase * 128)
        }
    }

frameCounter: .word 0
scrollCountdown: .byte SCROLL_FRAME_INTERVAL
incomingTile: .byte 0
tilePixelX: .byte 0
prefillLeft: .byte 0
incomingColumn: .fill TV_HEIGHT * 8, 0
activeLevel: .byte 0
levelTransition: .byte 0
levelCameraStep: .word 0
terrainScreenColors: .byte TERRAIN_SCREEN_COLORS
tvFillScreen: .byte 0
tvFillAccent: .byte 0
actorPlayerHeight: .byte SPRITE_GIANA_HEIGHT

.assert "Renderer fits below BASIC ROM", * <= $a000, true
.assert "Light tables contain three screen and color-RAM levels", lighting.getSize(), LIGHT_TILE_COUNT * 6
.assert "Terrain shares the picture background", BACKGROUND, TERRAIN_BACKGROUND
.assert "Terrain height matches the TV", TERRAIN_MAP_HEIGHT, TV_HEIGHT
.assert "Map wraps with a bit mask", (TERRAIN_MAP_WIDTH & (TERRAIN_MAP_WIDTH - 1)), 0
.assert "Tile addresses start on a page boundary", <terrainTiles, 0
.assert "Tile IDs fit in a byte", TERRAIN_TILE_COUNT <= 256, true
.assert "Accent flags start on a page boundary", <terrainAccentMap, 0
.assert "Accent flag bits cover the TV rows", TV_HEIGHT, 8
.assert "Accent phases use 128 map columns", TERRAIN_MAP_WIDTH, 128
.assert "Perspective columns cover the TV", TERRAIN_PERSPECTIVE_COLUMNS.get(TERRAIN_PERSPECTIVE_REGIONS), TV_WIDTH
.assert "Perspective boundaries include both TV edges", TERRAIN_PERSPECTIVE_COLUMNS.size(), TERRAIN_PERSPECTIVE_REGIONS + 1
.for (var region = 0; region < TERRAIN_PERSPECTIVE_REGIONS; region++) {
    .var rows = TERRAIN_PERSPECTIVE_SOURCE_ROWS.get(region)
    .assert "Perspective region covers every raster row", rows.size(), TV_HEIGHT * 8
}

.assert "Terrain renderer fits below enemy schedules", * <= $8600, true
* = $9000 "Tiny actor movement and clipping"
    .import source "sprites.asm"
.assert "Sprite helpers fit below BASIC ROM", * <= $a000, true

* = $9800 "Level selection and transitions"
initTerrain:
    jsr selectLevel
    // Initialize shared colors; the map selects each cell's accent below.
    lda terrainScreenColors
    ldy #5
    jsr setTVColors

    // Mask the fixed stepped edges; code 3 becomes black in their cells.
    lda #$ff
    .for (var region = 0; region < TERRAIN_PERSPECTIVE_REGIONS; region++) {
        .var rows = TERRAIN_PERSPECTIVE_SOURCE_ROWS.get(region)
        .for (var line = 0; line < TV_HEIGHT * 8; line++) {
            .if (rows.get(line) < 0) {
                .var address = BITMAP + ((TV_ROW + floor(line / 8)) * 40 + TV_COLUMN) * 8 + (line & 7)
                .for (var column = TERRAIN_PERSPECTIVE_COLUMNS.get(region); column < TERRAIN_PERSPECTIVE_COLUMNS.get(region + 1); column++) {
                    sta address + column * 8
                }
            }
        }
    }

    // Forty incoming columns replace the white area and stray side strips.
    jsr prepareColumn
    lda #TV_PIXELS
    sta prefillLeft
!prefill:
    jsr scrollTerrain
    dec prefillLeft
    bne !prefill-
    jsr updateColors
    rts

setTVColors:
    sta tvFillScreen
    sty tvFillAccent
    ldx #0
!colors:
    lda tvFillScreen
    .for (var row = 0; row < TV_HEIGHT; row++) {
        sta SCREEN + (TV_ROW + row) * 40 + TV_COLUMN,x
    }
    lda tvFillAccent
    .for (var row = 0; row < TV_HEIGHT; row++) {
        sta $d800 + (TV_ROW + row) * 40 + TV_COLUMN,x
    }
    inx
    cpx #TV_WIDTH
    bne !colors-
    rts

selectLevel:
    // Patch only source addresses; both levels share the raster-time renderer.
    ldx activeLevel
    .for (var row = 0; row < TV_HEIGHT; row++) {
        lda levelMapLow + row * 2,x
        sta terrainMapReadOperands.get(row)
        lda levelMapHigh + row * 2,x
        sta terrainMapReadOperands.get(row) + 1
    }
    lda levelTileHigh,x
    .for (var row = 0; row < TV_HEIGHT; row++) {
        sta terrainTileHighOperands.get(row)
    }
    .for (var region = 0; region < TERRAIN_PERSPECTIVE_REGIONS; region++) {
        .for (var phase = 0; phase < 4; phase++) {
            .var entry = region * 4 + phase
            lda levelAccentLow + entry * 2,x
            sta perspectiveAccentPhaseLow + entry
            lda levelAccentHigh + entry * 2,x
            sta perspectiveAccentPhaseHigh + entry
        }
    }
    lda levelScreenColors,x
    sta terrainScreenColors
    lda levelPlayerHeight,x
    sta actorPlayerHeight
    lda levelSpriteHigh,x
    .for (var frame = 0; frame < 4; frame++) {
        sta actorFrameHigh + frame
    }
    clc
    adc #1
    .for (var frame = 4; frame < 8; frame++) {
        sta actorFrameHigh + frame
    }
    lda levelPathHigh,x
    sta actorPlayerPathFirstRead + 2
    clc
    adc #1
    sta actorPlayerPathSecondRead + 2
    lda #0
    sta incomingTile
    sta tilePixelX
    sta levelCameraStep
    sta levelCameraStep + 1
    rts

advanceLevelTransition:
    // Spread the refill over PAL frames so the SID still ticks every frame.
    cmp #$ff
    beq !begin+
    cmp #$fe
    beq !reveal+
    lda lightCountdown
    cmp #1
    beq !done+
    jsr scrollTerrain
    dec levelTransition
    bne !done+
    lda #$fe
    sta levelTransition
!done:
    rts
!begin:
    lda activeLevel
    eor #1
    sta activeLevel
    jsr selectLevel
    lda #$99
    ldy #9
    jsr setTVColors
    lda #$07
    sta $d015
    lda #$06
    sta $d010
    jsr prepareColumn
    lda #TV_PIXELS
    sta levelTransition
    rts
!reveal:
    lda lightCountdown
    cmp #1
    beq !done-
    lda terrainScreenColors
    ldy #5
    jsr setTVColors
    jsr updateColors
    jsr updateSprites
    // Keep scrolling, sprite copies and room lighting on separate frames.
    lda frameCounter
    and #3
    eor #3
    bne !countdown+
    lda #SCROLL_FRAME_INTERVAL
!countdown:
    sta scrollCountdown
    lda #0
    sta levelTransition
    rts

levelTileHigh: .byte >terrainTiles, >terrain2Tiles
levelEndStepLow: .byte <512, <(512 - TV_PIXELS)
levelEndStepHigh: .byte >512, >(512 - TV_PIXELS)
levelScreenColors: .byte TERRAIN_SCREEN_COLORS, TERRAIN2_SCREEN_COLORS
levelPlayerHeight: .byte SPRITE_GIANA_HEIGHT, 8
levelSpriteHigh: .byte >tinySpriteFrames, >tinySpriteFrames2
levelPathHigh: .byte >actorPlayerPath, >actorPlayerPath2
levelMapLow:
    .for (var row = 0; row < TV_HEIGHT; row++) {
        .byte <(terrainMapStart + row * TERRAIN_MAP_WIDTH), <(terrain2MapStart + row * TERRAIN_MAP_WIDTH)
    }
levelMapHigh:
    .for (var row = 0; row < TV_HEIGHT; row++) {
        .byte >(terrainMapStart + row * TERRAIN_MAP_WIDTH), >(terrain2MapStart + row * TERRAIN_MAP_WIDTH)
    }
levelAccentLow:
    .for (var region = 0; region < TERRAIN_PERSPECTIVE_REGIONS; region++) {
        .for (var phase = 0; phase < 4; phase++) {
            .byte <(TERRAIN_PERSPECTIVE_ACCENT_MAPS.get(region) + phase * 128)
            .byte <(TERRAIN2_PERSPECTIVE_ACCENT_MAPS.get(region) + phase * 128)
        }
    }
levelAccentHigh:
    .for (var region = 0; region < TERRAIN_PERSPECTIVE_REGIONS; region++) {
        .for (var phase = 0; phase < 4; phase++) {
            .byte >(TERRAIN_PERSPECTIVE_ACCENT_MAPS.get(region) + phase * 128)
            .byte >(TERRAIN2_PERSPECTIVE_ACCENT_MAPS.get(region) + phase * 128)
        }
    }
.assert "Level switching fits below terrain", * <= $a000, true

.assert "Level switching avoids the enemy renderer", * <= $9b00, true
* = $9b00 "Corner reuse and original enemy display"
restoreLeftTopCorner:
    // The lower-left mask has finished before the next top-left DMA begins.
    lda #CORNER_SPRITES / 64
    sta SCREEN + $3f8
    lda #ACTOR_Y_BASE
    sta $d001
    rts

updateLevel2Enemies:
    // Three compact schedules per slot replace per-frame game AI.
    ldy actorStepLo
    lda actorStepHi
    beq !firstPage+
    .for (var enemy = 0; enemy < 2; enemy++) {
        .var xSource = enemy == 0 ? level2Enemy0X : level2Enemy1X
        .var ySource = enemy == 0 ? level2Enemy0Y : level2Enemy1Y
        .var frameSource = enemy == 0 ? level2Enemy0Frame : level2Enemy1Frame
        lda xSource + $100,y
        sta level2EnemyXs + enemy
        lda ySource + $100,y
        sta level2EnemyYs + enemy
        lda frameSource + $100,y
        sta level2EnemyFrames + enemy
    }
    jmp !loaded+
!firstPage:
    .for (var enemy = 0; enemy < 2; enemy++) {
        .var xSource = enemy == 0 ? level2Enemy0X : level2Enemy1X
        .var ySource = enemy == 0 ? level2Enemy0Y : level2Enemy1Y
        .var frameSource = enemy == 0 ? level2Enemy0Frame : level2Enemy1Frame
        lda xSource,y
        sta level2EnemyXs + enemy
        lda ySource,y
        sta level2EnemyYs + enemy
        lda frameSource,y
        sta level2EnemyFrames + enemy
    }
!loaded:
    lda #$06
    sta actorXHigh
    .for (var enemy = 0; enemy < 2; enemy++) {
        lda level2EnemyXs + enemy
        sta actorX
        lda level2EnemyFrames + enemy
        cmp #$ff
        beq !hidden+
        jsr setActorClip
        beq !hidden+
        lda level2EnemyFrames + enemy
        ldx #enemy + 2
        jsr copyTinySprite
        ldx actorSourceFrame
        lda actorFrameColor,x
        sta $d02d + enemy
        lda level2EnemyYs + enemy
        clc
        adc #ACTOR_Y_BASE
        sta $d00d + enemy * 2
        lda actorEnabled
        ora #(1 << (6 + enemy))
        sta actorEnabled
        lda actorX
        bmi !plotX+
        cmp #24
        bcc !plotX+
        lda actorXHigh
        ora #(1 << (6 + enemy))
        sta actorXHigh
        jmp !plotX+
!hidden:
        lda #0
        sta actorMask0
        sta actorMask1
        sta $d00d + enemy * 2
        lda #SPRITE_ENEMY_FRAME_OFFSET
        ldx #enemy + 2
        jsr copyTinySprite
!plotX:
        lda actorX
        asl
        clc
        adc #ACTOR_X_BASE
        sta $d00c + enemy * 2
    }
    lda actorXHigh
    sta $d010
    lda actorEnabled
    sta $d015
    rts

level2EnemyXs: .fill 2, 0
level2EnemyYs: .fill 2, 0
level2EnemyFrames: .fill 2, $ff
actorXHigh: .byte $06
.assert "Enemy display code fits below terrain", * <= $a000, true

* = $bb00 "Level 2 Giana route"
actorPlayerPath2:
    .import binary "assets/level2-sprite-player-path.bin"
.assert "Level 2 route covers the complete map", * - actorPlayerPath2, 512
